{%- comment -%}
CURVJEANS — Social Proof Badge (Inline PDP Version)
{%- endcomment -%}

{%- liquid
assign _lc = request.locale.iso_code | downcase

case _lc
  when "nl"
    assign spt = "<strong>10.000+</strong> vonden hun perfecte fit"
  when "de"
    assign spt = "<strong>10.000+</strong> Frauen lieben die Passform"
  else
    assign spt = "<strong>10,000+</strong> found their perfect fit"
endcase
-%}

<a href="#pdp-reviews" class="cj-spb-wrapper" aria-label="Read reviews">

  <div class="cj-spb-avatars">
    <img src="https://cdn.shopify.com/s/files/1/0864/5165/0895/files/customer_2.jpg?v=1761889230" alt="customer 1">
    <img src="https://cdn.shopify.com/s/files/1/0864/5165/0895/files/458401446_861392519278045_7170310081411598418_n.jpg?v=1763781967" alt="customer 2">
    <img src="https://cdn.shopify.com/s/files/1/0864/5165/0895/files/143996871_2715931985385887_965993897469689912_n.jpg?v=1763781966" alt="customer 3">
  </div>

  <div class="cj-spb-text">
    <span>{{ spt }}</span>
    <img class="cj-spb-verified"
         src="https://cdn.shopify.com/s/files/1/0864/5165/0895/files/verified.webp?v=1726649878"
         alt="verified">
  </div>

</a>

<style>
.cj-spb-wrapper {
  display: flex;
  justify-content: center;
  align-items: center;
  gap: 10px;
  margin: 16px auto;
  padding: 0;
  text-decoration: none;
  -webkit-tap-highlight-color: transparent;
}

.cj-spb-avatars {
  display: flex;
  align-items: center;
}

.cj-spb-avatars img {
  width: 28px;
  height: 28px;
