}

.cj-spb-avatars img:first-child {
  margin-left: 0;
}

.cj-spb-text {
  font-size: 14px;
  line-height: 1;
  font-weight: 500;
  display: flex;
  align-items: center;
  gap: 4px;
  color: #222; /* adjust to theme if needed */
}

.cj-spb-text strong {
  font-weight: 700;
}

.cj-spb-verified {
  width: 14px;
  height: 14px;
  flex-shrink: 0;
}

